#!/usr/bin/env python3
"""Writes CHANGELOG.md: what changed, and the status of every audit finding."""
import re, pathlib
R = pathlib.Path(__file__).parent.parent
F = {}
for block in (R / 'findings-list.txt').read_text().split('\n\n'):
    m = re.match(r'\[([a-z0-9-]+)\] (\w+) (\w+) \| (.*)', block.strip())
    if m: F[m.group(1)] = (m.group(2), m.group(4))
CHECKED = set()
for c in re.findall(r"check\('([^']+)'", (R / 'harness/checks.js').read_text()):
    CHECKED.update(c.split('/'))

